def populate_existing_points(apps, schema_editor):
    Score = apps.get_model('game', 'Score')
    scores = []

    for score in Score.objects.all():
        time_seconds = max(score.time_spent / 1000, 0.001)
        penalty = time_seconds + (score.moves * 2)
        score.points = max(1, round(60000 / penalty))
        scores.append(score)

    if scores:
        Score.objects.bulk_update(scores, ['points'])


def clear_existing_points(apps, schema_editor):
    Score = apps.get_model('game', 'Score')
    Score.objects.update(points=0)


